// READ ONLY.
const PIDS = ['31393214664f295f94dd86.76792605', '9933660066825e9a8005c8.58526829'];
return PIDS.map(function (p) { return { json: { url: 'https://api.lokalise.com/api2/projects/' + p + '/languages?limit=500' } }; });

const SINCE_TS = Math.floor(Date.parse('2026-10-03T00:00:00+02:00') / 1000);
const out = [];
for (const it of $input.all()) { const b = it.json.body || {}; if (!Array.isArray(b.languages)) continue;
  for (const l of b.languages) { if (['en', 'pst', 'cus'].includes(l.lang_iso)) continue;
    out.push({ json: { project_id: b.project_id, project_name: b.project_id, iso: l.lang_iso, lang_id: l.lang_id, lang_name: l.lang_name, since_ts: SINCE_TS } }); } }
return out;

// Learn set = keys with a translation changed since SINCE (any editor; filtered later). Target set = SO/OCD/PS tags.
const ids = {}; const scan = [];
for (const it of $input.all()) { const j = it.json || {}; scan.push({ p: j.project_id, iso: j.iso, seen: j.translations_seen, n: (j.changed || []).length, err: (j.errors || []).slice(0, 2) });
  for (const c of (j.changed || [])) { if (/efuturemedia/i.test(c.by || '') || !c.by) continue; (ids[j.project_id] = ids[j.project_id] || new Set()).add(c.key_id); } }
const A = 'https://api.lokalise.com/api2/projects/';
const Q = '/keys?include_translations=1&include_comments=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor';
const out = [];
for (const p of Object.keys(ids)) { const arr = [...ids[p]]; for (let i = 0; i < arr.length; i += 150) out.push({ json: { kind: 'learn', url: A + p + Q + '&filter_key_ids=' + arr.slice(i, i + 150).join(',') } }); }
out.push({ json: { kind: 'target', url: A + '31393214664f295f94dd86.76792605' + Q + '&filter_tags=' + encodeURIComponent('test::so,test::ocd,test::ps,emails::welcome::so,emails::welcome::ocd,emails::welcome::ps') } });
out.push({ json: { kind: 'target', url: A + '9933660066825e9a8005c8.58526829' + Q + '&filter_tags=' + encodeURIComponent('test_questions::so,test_questions::ocd,test_questions::ps') } });
out[0].json.scan = scan;
return out;

// READ ONLY.
const SINCE = '2026-10-03';
const TARGET = /^(test_questions::|test::|emails::welcome::)(so|ocd|ps)$/;
const out = { scan: $('Build key jobs').first().json.scan || [], errors: [], editors: {}, target: [], learn: [] };
const seen = {};
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || n.ios || n.android || ''); }
function s(v) { return typeof v === 'string' ? v : JSON.stringify(v); }
for (const it of $input.all()) { const b = it.json.body || {};
  if (!Array.isArray(b.keys)) { out.errors.push({ status: it.json.statusCode, body: JSON.stringify(b).slice(0, 300) }); continue; }
  for (const k of b.keys) { if (k.is_archived || seen[k.key_id]) continue; seen[k.key_id] = 1;
    const tags = Array.isArray(k.tags) ? k.tags.map(String) : [];
    const isTarget = tags.some(t => TARGET.test(t));
    const tr = k.translations || []; const en = tr.find(t => t.language_iso === 'en'); const ens = en ? s(en.translation) : '';
    let recent = false; const t = {};
    for (const x of tr) { const iso = x.language_iso; if (iso === 'en' || iso === 'pst' || iso === 'cus') continue;
      const tx = s(x.translation); if (!tx || tx === '{}') continue;
      const em = x.modified_by_email || ''; const ma = x.modified_at_timestamp ? new Date(x.modified_at_timestamp * 1000).toISOString().slice(0, 16) : '';
      if (ma >= SINCE && em && !/efuturemedia/i.test(em)) { recent = true; out.editors[em] = (out.editors[em] || 0) + 1; }
      t[iso] = [tx, em, ma, x.translation_id]; }
    const row = { p: b.project_id, i: k.key_id, k: kn(k), en: ens, d: String(k.description || '').slice(0, 400), cl: Number(k.char_limit || 0), tg: tags, pl: k.is_plural ? 1 : 0,
      c: (k.comments || []).map(x => String(x.comment || '')).filter(Boolean).join(' | ').slice(0, 300), t };
    if (isTarget) out.target.push(row); if (recent) out.learn.push(isTarget ? { ref: k.key_id } : row); } }
return [{ json: out }];
